// petdex hook plugin. Auto-generated by 'petdex hooks install'.
// Forwards OpenCode lifecycle events to the petdex desktop mascot via HTTP.
// Edit STATE_MAP below to customize which state each event triggers.

import { existsSync } from "node:fs";
import { readFile } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";

const HOOK_SERVER_URL = "http://127.0.0.1:7777/state";
const HOOK_SERVER_BUBBLE_URL = "http://127.0.0.1:7777/bubble";
const RUNTIME_DIR = join(homedir(), ".petdex", "runtime");
const TOKEN_PATH = join(RUNTIME_DIR, "update-token");
const KILLSWITCH_PATH = join(RUNTIME_DIR, "hooks-disabled");

async function readToken() {
  try {
    return (await readFile(TOKEN_PATH, "utf8")).trim();
  } catch {
    return null;
  }
}

function fieldFrom(input, key) {
  if (input == null || typeof input !== "object") return null;
  const value = input[key];
  return typeof value === "string" ? value : null;
}

function basename(filePath) {
  const slash = Math.max(filePath.lastIndexOf("/"), filePath.lastIndexOf("\\"));
  return slash >= 0 ? filePath.slice(slash + 1) : filePath;
}

function clip(text, max = 40) {
  return text.length <= max ? text : text.slice(0, max - 1) + "…";
}

// Warp gives each pane a link back to itself; the bubble's card offers it.
const WARP_FOCUS_URL = /^(warp|warppreview|warposs):\/\/session\/[0-9a-f]{32}$/;

function originMetadata() {
  const sourceApp = process.env.TERM_PROGRAM;
  const focusUrl = process.env.WARP_FOCUS_URL;
  // Only inside Warp: the variable is inherited by VS Code or tmux started
  // from a Warp pane, and a stale link would open the wrong pane.
  const warp = sourceApp === "WarpTerminal" && typeof focusUrl === "string" && WARP_FOCUS_URL.test(focusUrl) ? { warp_focus_url: focusUrl } : {};
  if (sourceApp !== "Apple_Terminal" && sourceApp !== "vscode") return warp;
  return {
    source_app: sourceApp,
    source_cwd: process.cwd(),
    ...warp,
  };
}

function canonicalToolKind(toolName) {
  const lower = String(toolName || "").toLowerCase();
  if (lower === "read") return "read";
  if (lower === "edit" || lower === "multiedit") return "edit";
  if (lower === "write") return "write";
  if (lower === "bash" || lower === "shell") return "bash";
  if (lower === "grep") return "grep";
  if (lower === "glob") return "glob";
  if (lower === "webfetch" || lower === "websearch") return "webfetch";
  if (lower === "task" || lower === "agent") return "task";
  return "unknown";
}

function formatTool(toolName, toolInput, phase) {
  const past = phase === "done";
  switch (canonicalToolKind(toolName)) {
    case "read": {
      const path = fieldFrom(toolInput, "file_path") ?? fieldFrom(toolInput, "filePath") ?? fieldFrom(toolInput, "path");
      const name = path ? clip(basename(path)) : null;
      return name ? (past ? "Read " + name : "Reading " + name) : past ? "Read file" : "Reading file";
    }
    case "edit":
    case "write": {
      const path = fieldFrom(toolInput, "file_path") ?? fieldFrom(toolInput, "filePath") ?? fieldFrom(toolInput, "path");
      const name = path ? clip(basename(path)) : null;
      return name ? (past ? "Edited " + name : "Editing " + name) : past ? "Edited file" : "Editing file";
    }
    case "bash": {
      const command = fieldFrom(toolInput, "command");
      if (command) {
        const head = clip(command.split(/\s+/)[0] || command, 24);
        return past ? "Ran " + head : "Running " + head;
      }
      return past ? "Ran command" : "Running command";
    }
    case "grep": {
      const pattern = fieldFrom(toolInput, "pattern");
      // Curly quotes: JSON.stringify escapes an ASCII `"` correctly, but
      // the hook server reads the body back with a scanner that stops at the
      // backslash, so the pattern never reaches the bubble.
      return pattern ? (past ? "Searched “" + clip(pattern, 28) + "”" : "Searching “" + clip(pattern, 28) + "”") : past ? "Searched files" : "Searching files";
    }
    case "glob": {
      const pattern = fieldFrom(toolInput, "pattern");
      return pattern ? (past ? "Listed " + clip(pattern, 28) : "Listing " + clip(pattern, 28)) : past ? "Listed files" : "Listing files";
    }
    case "webfetch": {
      const url = fieldFrom(toolInput, "url");
      if (url) {
        try {
          const host = new URL(url).hostname;
          return past ? "Fetched " + clip(host, 28) : "Fetching " + clip(host, 28);
        } catch {}
      }
      return past ? "Fetched web" : "Searching web";
    }
    case "task":
      return past ? "Subagent done" : "Spawning subagent";
    default: {
      const name = clip(String(toolName || "tool"), 28);
      return past ? "Called " + name : "Calling " + name;
    }
  }
}

async function postJson(url, body, token) {
  try {
    await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Petdex-Update-Token": token,
      },
      body: JSON.stringify(body),
      // 300ms instead of 1s: well above any real localhost roundtrip
      // and below the threshold an agent user notices as latency.
      signal: AbortSignal.timeout(300),
    });
  } catch {
    // Hook server offline: stay quiet, the agent should not notice.
  }
}

async function notify({ state, duration, text, title, busy, sessionId, model, agentState }) {
  // Killswitch: users toggle this with /petdex inside their agent
  // (or 'petdex hooks toggle' from a shell). Bail before the token
  // read so the disabled state has zero filesystem cost beyond the
  // existsSync.
  if (existsSync(KILLSWITCH_PATH)) return;
  // Token gate defends against drive-by no-cors POSTs from any site
  // the user visits. The token rotates per desktop session and lives
  // at mode 0600, so only this user can read it.
  const token = await readToken();
  if (!token) return; // Hook server offline or missing; silently no-op.
  // Stamp agent_source so the hook server can route per-pet when we
  // ship multi-mascot. Today the field is recorded for telemetry
  // but doesn't affect routing.
  const stateBody =
    duration != null
      ? { state, duration, agent_source: "opencode" }
      : { state, agent_source: "opencode" };
  const metadata = originMetadata();
  Object.assign(stateBody, metadata);
  const bubbleBody = { text, agent_source: "opencode", ...metadata };
  if (sessionId) {
    stateBody.session_id = sessionId;
    bubbleBody.session_id = sessionId;
  }
  if (title) bubbleBody.title = title;
  if (busy !== undefined) bubbleBody.busy = busy;
  // The card shows the model; a failed session keeps its bubble, marked,
  // instead of popping as done.
  if (model) bubbleBody.model = model;
  if (agentState) bubbleBody.agent_state = agentState;
  await Promise.all([
    postJson(HOOK_SERVER_URL, stateBody, token),
    text ? postJson(HOOK_SERVER_BUBBLE_URL, bubbleBody, token) : Promise.resolve(),
  ]);
}

// opencode's plugin API: the export IS an async function receiving
// the plugin context and returning the hooks object. The client gives
// us opencode's own LLM-generated session titles for the bubble.
const PetdexPlugin = async ({ client }) => {
  const titleCache = new Map();
  // The model each session's assistant last answered with, from its
  // message.updated events.
  const modelCache = new Map();
  const failedSessions = new Set();
  async function sessionTitle(sessionID) {
    if (!sessionID || !client) return titleCache.get(sessionID) || null;
    try {
      const res = await client.session.get({ path: { id: sessionID } });
      const title = res?.data?.title;
      if (typeof title === "string" && title.length > 0) {
        titleCache.set(sessionID, title.length > 60 ? title.slice(0, 59) + "\u2026" : title);
      }
    } catch {
      // Hook-server silence: a missing title never stains the agent.
    }
    return titleCache.get(sessionID) || null;
  }
  return {
    "tool.execute.before": async (input, output) => notify({
      state: "running",
      text: formatTool(input.tool, output.args, "running"),
      title: await sessionTitle(input.sessionID),
      busy: true,
      sessionId: input.sessionID,
      model: modelCache.get(input.sessionID),
    }),
    "tool.execute.after": async (input) => notify({
      state: "idle",
      text: formatTool(input.tool, input.args, "done"),
      title: await sessionTitle(input.sessionID),
      busy: true,
      sessionId: input.sessionID,
      model: modelCache.get(input.sessionID),
    }),
    event: async ({ event }) => {
      // The host's bus has shipped both properties and data envelopes.
      const properties = event?.properties ?? event?.data;
      // A message event carries its session inside `info`, not as
      // properties.sessionID, so it is handled before that check.
      if (event?.type === "message.updated") {
        const info = properties?.info;
        if (info?.role === "user" && typeof info.sessionID === "string") failedSessions.delete(info.sessionID);
        if (info?.role === "assistant" && typeof info.sessionID === "string" && typeof info.modelID === "string") {
          modelCache.set(info.sessionID, info.modelID);
        }
        return;
      }
      const sessionId = properties?.sessionID;
      if (typeof sessionId !== "string" || sessionId.length === 0) return;
      if (event.type === "session.deleted") {
        failedSessions.delete(sessionId);
        titleCache.delete(sessionId);
        modelCache.delete(sessionId);
        return;
      }
      if (event.type === "session.status" && properties.status?.type === "busy") {
        failedSessions.delete(sessionId);
        return;
      }
      if (["permission.asked", "permission.v2.asked", "question.asked", "question.v2.asked"].includes(event.type)) {
        await notify({
          state: "waiting",
          text: event.type.startsWith("permission.") ? "Waiting for approval…" : "Waiting for your answer…",
          title: await sessionTitle(sessionId),
          busy: false,
          sessionId,
          model: modelCache.get(sessionId),
          agentState: "waiting",
        });
      } else if (["permission.replied", "permission.v2.replied", "question.replied", "question.v2.replied", "question.rejected", "question.v2.rejected"].includes(event.type)) {
        // Observe the resolved prompt; never return a permission decision.
        // A denial/rejection still resumes the agent so it can react.
        await notify({
          state: "running",
          text: "Continuing…",
          title: await sessionTitle(sessionId),
          busy: true,
          sessionId,
          model: modelCache.get(sessionId),
          agentState: "running",
        });
      } else if (event.type === "session.idle") {
        // An error also settles the host to idle. That is not a successful
        // completion; retain the failure until a new turn actually starts.
        if (failedSessions.has(sessionId)) return;
        await notify({
          state: "waving",
          duration: 1500,
          text: "Done.",
          title: await sessionTitle(sessionId),
          busy: false,
          sessionId,
          model: modelCache.get(sessionId),
        });
      } else if (event.type === "session.error") {
        failedSessions.add(sessionId);
        await notify({
          state: "failed",
          duration: 2500,
          text: "OpenCode hit an error.",
          title: await sessionTitle(sessionId),
          busy: false,
          sessionId,
          model: modelCache.get(sessionId),
          agentState: "failed",
        });
      }
    },
  };
};

export default PetdexPlugin;
export { PetdexPlugin };
